import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"10、【履】 兑下乾上","description":"温公易说 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"温公易说 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/wengong/011.md","filePath":"zh/classics/wengong/011.md"}'),n={name:"zh/classics/wengong/011.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><h3 id="彖曰-履-柔履刚也-说而应乎干-是以履虎尾不咥人-亨。刚中正履-帝位而不疚-光明也。" tabindex="-1">彖曰：履，柔履刚也，说而应乎干，是以履虎尾不咥人，亨。刚中正履，帝位而不疚，光明也。 <a class="header-anchor" href="#彖曰-履-柔履刚也-说而应乎干-是以履虎尾不咥人-亨。刚中正履-帝位而不疚-光明也。" aria-label="Permalink to “彖曰：履，柔履刚也，说而应乎干，是以履虎尾不咥人，亨。刚中正履，帝位而不疚，光明也。”">​</a></h3><h3 id="象曰-上天下泽-履。君子以辨上下-定民志。" tabindex="-1">象曰：上天下泽，履。君子以辨上下，定民志。 <a class="header-anchor" href="#象曰-上天下泽-履。君子以辨上下-定民志。" aria-label="Permalink to “象曰：上天下泽，履。君子以辨上下，定民志。”">​</a></h3><p>履者何？人之所履也。人之所履者何？礼之谓也。人有礼则生，无礼则死。礼者，人所履之常也。其曰辨上下，定民志者何？夫民生有欲，喜进务得而不可厌者也。不以礼节之，则贪淫侈溢而无穷也。是故先王作为礼以治之，使尊卑有等，长幼有伦，内外有别，亲疏有序，然后上下各安其分而无觊觎之心。此先王制世御民之方也。</p><h3 id="初九-素履-往无咎-象曰-素履之往-独行愿也。" tabindex="-1">初九：素履，往无咎 象曰：素履之往，独行愿也。 <a class="header-anchor" href="#初九-素履-往无咎-象曰-素履之往-独行愿也。" aria-label="Permalink to “初九：素履，往无咎 象曰：素履之往，独行愿也。”">​</a></h3><h3 id="九二-履道坦坦-幽人贞吉-象曰-幽人贞吉-中不自乱也。" tabindex="-1">九二：履道坦坦，幽人贞吉 象曰：幽人贞吉，中不自乱也。 <a class="header-anchor" href="#九二-履道坦坦-幽人贞吉-象曰-幽人贞吉-中不自乱也。" aria-label="Permalink to “九二：履道坦坦，幽人贞吉 象曰：幽人贞吉，中不自乱也。”">​</a></h3><h3 id="六三-眇能视-跛能履-履虎尾-咥人凶。武人为于大君-象曰-眇能视-不足以有明也-跛能履-不足以与行也。咥人之凶-位不当也。武人为于大君-志刚也。" tabindex="-1">六三：眇能视，跛能履，履虎尾，咥人凶。武人为于大君 象曰：眇能视，不足以有明也；跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。 <a class="header-anchor" href="#六三-眇能视-跛能履-履虎尾-咥人凶。武人为于大君-象曰-眇能视-不足以有明也-跛能履-不足以与行也。咥人之凶-位不当也。武人为于大君-志刚也。" aria-label="Permalink to “六三：眇能视，跛能履，履虎尾，咥人凶。武人为于大君 象曰：眇能视，不足以有明也；跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。”">​</a></h3><h3 id="九四-履虎尾-诉诉-终吉-象曰-诉诉终吉-志行也。" tabindex="-1">九四：履虎尾，诉诉，终吉 象曰：诉诉终吉，志行也。 <a class="header-anchor" href="#九四-履虎尾-诉诉-终吉-象曰-诉诉终吉-志行也。" aria-label="Permalink to “九四：履虎尾，诉诉，终吉 象曰：诉诉终吉，志行也。”">​</a></h3><h3 id="九五-夬履-贞厉-象曰-夬履贞厉-位正当也。" tabindex="-1">九五：夬履，贞厉 象曰：夬履贞厉，位正当也。 <a class="header-anchor" href="#九五-夬履-贞厉-象曰-夬履贞厉-位正当也。" aria-label="Permalink to “九五：夬履，贞厉 象曰：夬履贞厉，位正当也。”">​</a></h3><p>夬者，决也。履者，人之所履也。人之所履有得有失，为人君者决而正之，得则有赏，失则有法。劝赏畏刑，然后人莫敢不慎其履，而天下国家可得而治也。五以刚健为履之主，乘其中正以决得失，任斯重也，可不戒乎？故曰贞厉。</p><h3 id="上九-视履-考祥-其旋-元吉-象曰-元吉在上-大有庆也。" tabindex="-1">上九：视履，考祥，其旋，元吉 象曰：元吉在上，大有庆也。 <a class="header-anchor" href="#上九-视履-考祥-其旋-元吉-象曰-元吉在上-大有庆也。" aria-label="Permalink to “上九：视履，考祥，其旋，元吉 象曰：元吉在上，大有庆也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
